      "items": {
        "ui:order": [
          "type",
          "description",
          "relatedGoal",
          "dueDate",
          "status",
          "outcome"
        ],
        "description": {
          "ui:widget": "textarea",
          "ui:options": {
            "rows": 3
          }
        },
        "outcome": {
          "ui:widget": "textarea",
          "ui:options": {
            "rows": 3
          }
        }
      },
      "ui:options": {
        "addable": false,
        "removable": false,
        "orderable": false
      },
      "ui:readonly": true
    },
    "ProgressReviews": {
      "items": {
        "ui:order": [
          "date",
          "onTrack",
          "notes",
          "adjustments",
          "planCompleted"
        ],
        "notes": {
          "ui:widget": "textarea",
          "ui:options": {
            "rows": 3
          }
        },
        "adjustments": {
          "ui:widget": "textarea",
          "ui:options": {
            "rows": 3
          }
        }
      },
      "ui:options": {
        "addable": false,
        "removable": false,
        "orderable": false
      },
      "ui:readonly": true
    },
    "SelfAssessment": {
      "ui:order": [
        "goalResults",
        "summary"
      ],
      "goalResults": {
        "items": {
          "ui:order": [
            "goalTitle",
            "result",
            "comments"
          ],
          "comments": {
            "ui:widget": "textarea",
            "ui:options": {
              "rows": 3
            }
          }
        },
        "ui:options": {
          "addable": false,
          "removable": false,
          "orderable": false
        },
        "ui:readonly": true
      },
      "summary": {
        "ui:widget": "textarea",
        "ui:options": {
          "rows": 3
        }
      },
      "ui:readonly": true
    },
    "Evaluation": {
      "ui:order": [
        "outcome",
        "summary",
        "goalResults",
        "furtherDevelopment"
      ],
      "summary": {
        "ui:widget": "textarea",
        "ui:options": {
          "rows": 3
        }
      },
      "goalResults": {
        "items": {
          "ui:order": [
            "goalTitle",
            "result",
            "comments"
          ],
          "comments": {
            "ui:widget": "textarea",
            "ui:options": {
              "rows": 3
            }
          },
          "goalTitle": {
            "ui:readonly": true
          }
        },
        "ui:options": {
          "addable": false,
          "removable": false,
          "orderable": false
        }
      }
    },
    "ui:order": [
      "Plan",
      "Activities",
      "ProgressReviews",
      "SelfAssessment",
      "Evaluation"
    ]
  },
  "jsonforms": {
    "schema": {
      "title": "Evaluate & document results",
      "description": "Record the result per goal and overall. Tick \"Further development needed\" to start a new plan round; otherwise the plan is closed.",
      "type": "object",
      "required": [
        "Evaluation"
      ],
      "properties": {
        "Plan": {
          "type": "object",
          "title": "Development plan",
          "properties": {
            "period": {
              "type": "string",
              "title": "Plan period"
            },
            "goals": {
              "type": "array",
              "title": "Goals",
              "items": {
                "type": "object",
                "title": "Goal",
                "properties": {
                  "title": {
                    "type": "string",
                    "title": "Goal"
                  },
                  "type": {
                    "type": "string",
                    "title": "Type",
                    "oneOf": [
                      {
                        "const": "SKILL",
                        "title": "Skill"
                      },
                      {
                        "const": "KNOWLEDGE",
                        "title": "Knowledge"
                      },
                      {
                        "const": "BEHAVIOUR",
                        "title": "Behaviour"
                      },
                      {
                        "const": "CAREER",
                        "title": "Career"
                      }
                    ]
                  },
                  "description": {
                    "type": "string",
                    "title": "Description"
                  },
                  "successCriteria": {
                    "type": "string",
                    "title": "How we know it is achieved"
                  },
                  "targetDate": {
                    "type": "string",
                    "title": "Target date",
                    "format": "date"
                  }
                },
                "required": [
                  "title",
                  "type",
                  "successCriteria",
                  "targetDate"
                ]
              },
              "minItems": 1
            }
          },
          "required": [
            "period",
            "goals"
          ]
        },
        "Activities": {
          "type": "array",
          "title": "Activities in this round",
          "items": {
            "type": "object",
            "title": "Activity",
            "properties": {
              "type": {
                "type": "string",
                "title": "Type",
                "oneOf": [
                  {
                    "const": "PROJECT",
                    "title": "Project"
                  },
                  {
                    "const": "TRAINING",
                    "title": "Training"
                  },
                  {
                    "const": "COACHING",
                    "title": "Coaching"
                  }
                ]
              },
              "description": {
                "type": "string",
                "title": "Description"
              },
              "relatedGoal": {
                "type": "string",
                "title": "Supports goal"
              },
              "dueDate": {
                "type": "string",
                "title": "Due date",
                "format": "date"
              },
              "status": {
                "type": "string",
                "title": "Status",
                "oneOf": [
                  {
                    "const": "PLANNED",
                    "title": "Planned"
                  },
                  {
                    "const": "IN_PROGRESS",
                    "title": "In progress"
                  },
                  {
                    "const": "DONE",
                    "title": "Done"
                  }
                ]
              },
              "outcome": {
                "type": "string",
                "title": "Outcome"
              }
            }
          }
        },
        "ProgressReviews": {
          "type": "array",
          "title": "Progress reviews in this round",
          "items": {
            "type": "object",
            "title": "Review",
            "properties": {
              "date": {
                "type": "string",
                "title": "Review date",
                "format": "date"
              },
              "onTrack": {
                "type": "boolean",
                "title": "On track",
                "default": true
              },
              "notes": {
                "type": "string",
                "title": "Notes"
              },
              "adjustments": {
                "type": "string",
                "title": "Adjustments to the plan"
              },
              "planCompleted": {
                "type": "boolean",
                "title": "The plan has been carried out: start the evaluation",
                "default": false
              }
            }
          }
        },
        "SelfAssessment": {
          "type": "object",
          "title": "Self-assessment",
          "properties": {
            "goalResults": {
              "type": "array",
              "title": "Results per goal",
              "items": {
                "type": "object",
                "title": "Goal result",
                "properties": {
                  "goalTitle": {
                    "type": "string",
                    "title": "Goal"
                  },
                  "result": {
                    "type": "string",
                    "title": "Result",
                    "oneOf": [
                      {
                        "const": "EXCEEDED",
                        "title": "Exceeded"
                      },
                      {
                        "const": "MET",
                        "title": "Met"
                      },
                      {
                        "const": "PARTIALLY_MET",
                        "title": "Partially met"
                      },
                      {
                        "const": "NOT_MET",
                        "title": "Not met"
                      }
                    ]
                  },
                  "comments": {
                    "type": "string",
                    "title": "Comments"
                  }
                },
                "required": [
                  "goalTitle",
                  "result"
                ]
              }
            },
            "summary": {
              "type": "string",
              "title": "Summary"
            }
          },
          "required": [
            "summary"
          ]
        },
        "Evaluation": {
          "type": "object",
          "title": "Evaluation",
          "properties": {
            "outcome": {
              "type": "string",
              "title": "Outcome",
              "oneOf": [
                {
                  "const": "MET",
                  "title": "Met"
                },
                {
                  "const": "PARTIALLY_MET",
                  "title": "Partially met"
                },
                {
                  "const": "NOT_MET",
                  "title": "Not met"
                }
              ]
            },
            "summary": {
              "type": "string",
              "title": "Summary"
            },
            "goalResults": {
              "type": "array",
              "title": "Results per goal",
              "items": {
                "type": "object",
                "title": "Goal result",
                "properties": {
                  "goalTitle": {
                    "type": "string",
                    "title": "Goal"
                  },
                  "result": {
                    "type": "string",
                    "title": "Result",
                    "oneOf": [
                      {
                        "const": "EXCEEDED",
                        "title": "Exceeded"
                      },
                      {
                        "const": "MET",
                        "title": "Met"
                      },
                      {
                        "const": "PARTIALLY_MET",
                        "title": "Partially met"
                      },
                      {
                        "const": "NOT_MET",
                        "title": "Not met"
                      }
                    ]
                  },
                  "comments": {
                    "type": "string",
                    "title": "Comments"
                  }
                },
                "required": [
                  "goalTitle",
                  "result"
                ]
              }
            },
            "furtherDevelopment": {
              "type": "boolean",
              "title": "Further development needed: start a new plan round",
              "default": false
            }
          },
          "required": [
            "outcome",
            "summary",
            "furtherDevelopment"
          ]
        }
      }
    },
    "submitLabel": "Save evaluation",
    "uischema": {
      "type": "VerticalLayout",
      "elements": [
        {
          "type": "Group",
          "label": "Development plan",
          "elements": [
            {
              "type": "Control",
              "scope": "#/properties/Plan/properties/period",
              "options": {
                "readonly": true
              }
            },
            {
              "type": "Control",
              "scope": "#/properties/Plan/properties/goals",
              "options": {
                "showSortButtons": false,
                "elementLabelProp": "title",
                "detail": {
                  "type": "VerticalLayout",
                  "elements": [
                    {
                      "type": "Control",
                      "scope": "#/properties/title",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/type",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/description",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/successCriteria",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/targetDate",
                      "options": {
                        "readonly": true
                      }
                    }
                  ]
                },
                "disableAdd": true,
                "disableRemove": true,
                "readonly": true
              }
            }
          ]
        },
        {
          "type": "Group",
          "label": "Activities in this round",
          "elements": [
            {
              "type": "Control",
              "scope": "#/properties/Activities",
              "label": false,
              "options": {
                "disableAdd": true,
                "disableRemove": true,
                "showSortButtons": false,
                "elementLabelProp": "description",
                "detail": {
                  "type": "VerticalLayout",
                  "elements": [
                    {
                      "type": "Control",
                      "scope": "#/properties/type",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/description",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/relatedGoal",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/dueDate",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/status",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/outcome",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    }
                  ]
                },
                "readonly": true
              }
            }
          ]
        },
        {
          "type": "Group",
          "label": "Progress reviews in this round",
          "elements": [
            {
              "type": "Control",
              "scope": "#/properties/ProgressReviews",
              "label": false,
              "options": {
                "disableAdd": true,
                "disableRemove": true,
                "showSortButtons": false,
                "elementLabelProp": "date",
                "detail": {
                  "type": "VerticalLayout",
                  "elements": [
                    {
                      "type": "Control",
                      "scope": "#/properties/date",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/onTrack",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/notes",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/adjustments",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/planCompleted",
                      "options": {
                        "readonly": true
                      }
                    }
                  ]
                },
                "readonly": true
              }
            }
          ]
        },
        {
          "type": "Group",
          "label": "Self-assessment",
          "elements": [
            {
              "type": "Control",
              "scope": "#/properties/SelfAssessment/properties/goalResults",
              "options": {
                "showSortButtons": false,
                "elementLabelProp": "goalTitle",
                "detail": {
                  "type": "VerticalLayout",
                  "elements": [
                    {
                      "type": "Control",
                      "scope": "#/properties/goalTitle",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/result",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/comments",
                      "options": {
                        "multi": true,
                        "readonly": true
                      }
                    }
                  ]
                },
                "disableAdd": true,
                "disableRemove": true,
                "readonly": true
              }
            },
            {
              "type": "Control",
              "scope": "#/properties/SelfAssessment/properties/summary",
              "options": {
                "multi": true,
                "readonly": true
              }
            }
          ]
        },
        {
          "type": "Group",
          "label": "Evaluation",
          "elements": [
            {
              "type": "Control",
              "scope": "#/properties/Evaluation/properties/outcome"
            },
            {
              "type": "Control",
              "scope": "#/properties/Evaluation/properties/summary",
              "options": {
                "multi": true
              }
            },
            {
              "type": "Control",
              "scope": "#/properties/Evaluation/properties/goalResults",
              "options": {
                "showSortButtons": false,
                "elementLabelProp": "goalTitle",
                "detail": {
                  "type": "VerticalLayout",
                  "elements": [
                    {
                      "type": "Control",
                      "scope": "#/properties/goalTitle",
                      "options": {
                        "readonly": true
                      }
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/result"
                    },
                    {
                      "type": "Control",
                      "scope": "#/properties/comments",
                      "options": {
                        "multi": true
                      }
                    }
                  ]
                },
                "disableAdd": true,
                "disableRemove": true
              }
            },
            {
              "type": "Control",
              "scope": "#/properties/Evaluation/properties/furtherDevelopment"
            }
          ]
        }
      ]
    }
  },
  "output": "Evaluation"
}

extensionElements.cafienne:start-case-model:
{
  "schema": {
    "type": "object",
    "required": [
      "Employee"
    ],
    "properties": {
      "Employee": {
        "type": "object",
        "title": "Employee",
        "properties": {
          "employeeId": {
            "type": "string",
            "title": "Employee number"
          },
          "name": {
            "type": "string",
            "title": "Name"
          },
          "jobTitle": {
            "type": "string",
            "title": "Job title"
          },
          "managerId": {
            "type": "string",
            "title": "Manager number"
          },
          "managerName": {
            "type": "string",
            "title": "Manager"
          },
          "trigger": {
            "type": "string",
            "title": "Reason for the plan",
            "enum": [
              "ANNUAL_REVIEW",
              "NEW_ROLE",
              "CAREER_GROWTH",
              "PERFORMANCE_IMPROVEMENT",
              "ONBOARDING"
            ],
            "enumNames": [
              "Annual review",
              "New role",
              "Career growth",
              "Performance improvement",
              "Onboarding"
            ]
          }
        },
        "required": [
          "employeeId",
          "name",
          "managerId",
          "trigger"
        ]
      }
    }
  }
}
